namespace ModernHost {
public static class ProxyClientSetup {
private const string Provider="workspace-proxy",Begin="/* >>> multi-account-proxy-models >>> */",End="/* <<< multi-account-proxy-models <<< */";
public static string Executable(string client){string folder=client=="opencode"?"@opencode-aidesktop":"Command Code",exe=client=="opencode"?"OpenCode.exe":"Command Code.exe";return new[]{Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData)+"\\Programs",Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86)}.Select(root=>Path.Combine(root,folder,exe)).FirstOrDefault(File.Exists);}
public static object Status(){return new{commandcode=Executable("commandcode")!=null,opencode=Executable("opencode")!=null};}
public static bool Running(string client){string exe=Executable(client);if(exe==null)return false;foreach(var process in System.Diagnostics.Process.GetProcessesByName(Path.GetFileNameWithoutExtension(exe))){using(process){try{if(string.Equals(process.MainModule.FileName,exe,StringComparison.OrdinalIgnoreCase))return true;}catch{}}}return false;}
public static void Open(string client,bool restart){string exe=Executable(client);if(exe==null)throw new InvalidOperationException("未找到客户端");if(restart){foreach(var process in System.Diagnostics.Process.GetProcessesByName(Path.GetFileNameWithoutExtension(exe))){using(process){try{if(!string.Equals(process.MainModule.FileName,exe,StringComparison.OrdinalIgnoreCase))continue;if(process.MainWindowHandle!=IntPtr.Zero)process.CloseMainWindow();if(!process.WaitForExit(2500)){process.Kill();process.WaitForExit(2500);}}catch(System.ComponentModel.Win32Exception){throw new InvalidOperationException("客户端无法退出，请手动关闭后再打开");}catch(InvalidOperationException){}}}}System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(exe){UseShellExecute=true});}
public static async Task Configure(string client,string address,int port,string key){string exe=Executable(client);if(exe==null)throw new InvalidOperationException("未检测到客户端，请先安装官方程序");string url="http://"+address+":"+port+"/v1";Dictionary<string,object> listing;using(var http=new HttpClient(new HttpClientHandler{UseProxy=false}){Timeout=TimeSpan.FromSeconds(30)}){http.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",key);listing=Core.Json.Deserialize<Dictionary<string,object>>(await http.GetStringAsync(url+"/models"));}var models=(Core.Value(listing,"data") as System.Collections.IEnumerable);if(models==null)throw new InvalidOperationException("代理暂未返回可用模型，请检测账号池");var items=models.Cast<object>().Select(Core.Object).ToArray();if(items.Length==0)throw new InvalidOperationException("账号池暂时没有可用模型");Write(client,Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),Path.Combine(Path.GetDirectoryName(exe),"resources","app","out","main","index.js"),url,key,items);}
private static Dictionary<string,object> Read(string path){if(!File.Exists(path))return new Dictionary<string,object>();try{return Core.Json.Deserialize<Dictionary<string,object>>(Jsonc(File.ReadAllText(path,Encoding.UTF8)))??new Dictionary<string,object>();}catch{throw new InvalidOperationException("客户端配置格式无法解析，原文件未修改");}}
public static string Jsonc(string text){var result=new StringBuilder();bool quoted=false,escaped=false;for(int i=0;i<text.Length;i++){char c=text[i];if(quoted){result.Append(c);if(escaped)escaped=false;else if(c=='\\')escaped=true;else if(c=='"')quoted=false;continue;}if(c=='"'){quoted=true;result.Append(c);continue;}if(c=='/'&&i+1<text.Length&&text[i+1]=='/'){while(i<text.Length&&text[i]!='\n')i++;result.Append('\n');continue;}if(c=='/'&&i+1<text.Length&&text[i+1]=='*'){i+=2;while(i+1<text.Length&&!(text[i]=='*'&&text[i+1]=='/'))i++;i++;result.Append(' ');continue;}if(c==','){int j=i+1;while(j<text.Length&&char.IsWhiteSpace(text[j]))j++;if(j<text.Length&&(text[j]=='}'||text[j]==']'))continue;}result.Append(c);}return StripTrailingCommas(result.ToString());}
private static string StripTrailingCommas(string text){var output=new StringBuilder();bool quoted=false,escaped=false;for(int i=0;i<text.Length;i++){char c=text[i];if(quoted){output.Append(c);if(escaped)escaped=false;else if(c=='\\')escaped=true;else if(c=='"')quoted=false;continue;}if(c=='"')quoted=true;if(c==','){int j=i+1;while(j<text.Length&&char.IsWhiteSpace(text[j]))j++;if(j<text.Length&&(text[j]=='}'||text[j]==']'))continue;}output.Append(c);}return output.ToString();}
private static string Wire(Dictionary<string,object> model){var endpoints=Core.Value(model,"supported_endpoints") as System.Collections.IEnumerable;var routes=endpoints==null?new string[0]:endpoints.Cast<object>().Select(Convert.ToString).ToArray();if(routes.Any(r=>r.Contains("chat/completions")))return "openai-completions";if(routes.Any(r=>r.EndsWith("responses")))return "openai-responses";if(routes.Any(r=>r.EndsWith("messages")))return "anthropic-messages";return null;}
public static void Write(string client,string home,string mainPath,string url,string key,Dictionary<string,object>[] items){if(client!="opencode"&&client!="commandcode")throw new InvalidOperationException("不支持的客户端");var valid=items.Where(m=>Wire(m)!=null).ToArray();if(valid.Length==0)throw new InvalidOperationException("没有已确认协议的模型，未修改客户端");var writes=new Dictionary<string,string>();
if(client=="opencode"){string dir=Path.Combine(home,".config","opencode"),path=Path.Combine(dir,File.Exists(Path.Combine(dir,"opencode.jsonc"))?"opencode.jsonc":"opencode.json");var config=Read(path);var providers=Core.Object(Core.Value(config,"provider"));string first=null;foreach(string wire in new[]{"openai-completions","openai-responses","anthropic-messages"}){var models=new Dictionary<string,object>();foreach(var model in valid.Where(m=>Wire(m)==wire)){string id=Core.Text(model,"id");models[id]=new{name=id,id=id,limit=new{context=32768,output=4096}};}if(models.Count==0)continue;string idProvider=Provider+(wire=="openai-completions"?"-chat":wire=="openai-responses"?"-responses":"-messages");providers[idProvider]=new{name="工作台代理",npm=wire=="anthropic-messages"?"@ai-sdk/anthropic":wire=="openai-responses"?"@ai-sdk/openai":"@ai-sdk/openai-compatible",options=new{baseURL=url,apiKey=key},models=models};if(first==null)first=idProvider+"/"+models.Keys.First();var enabled=Core.Value(config,"enabled_providers") as System.Collections.IEnumerable;if(enabled!=null)config["enabled_providers"]=enabled.Cast<object>().Select(Convert.ToString).Concat(new[]{idProvider}).Distinct().ToArray();var disabled=Core.Value(config,"disabled_providers") as System.Collections.IEnumerable;if(disabled!=null)config["disabled_providers"]=disabled.Cast<object>().Select(Convert.ToString).Where(v=>v!=idProvider).ToArray();}config["provider"]=providers;config["model"]=first;config["small_model"]=first;writes[path]=Core.Json.Serialize(config);}
else{string folder=Path.Combine(home,".commandcode"),path=Path.Combine(folder,"providers.json"),authPath=Path.Combine(folder,"auth.json");var config=Read(path);var providers=Core.Object(Core.Value(config,"provider"));var models=new Dictionary<string,object>();foreach(var model in valid)models[Core.Text(model,"id")]=new{name=Core.Text(model,"id"),api=Wire(model),contextWindow=32768,maxOutput=4096};providers[Provider]=new{name="工作台代理",baseURL=url,models=models};config["provider"]=providers;var auth=Read(authPath);auth[Provider]=new{type="api",key=key};writes[path]=Core.Json.Serialize(config);writes[authPath]=Core.Json.Serialize(auth);if(!File.Exists(mainPath))throw new InvalidOperationException("当前桌面版没有可接入的模型列表，原配置未修改");string source=File.ReadAllText(mainPath,Encoding.UTF8);if(!source.Contains("MODEL_OPTIONS")||!source.Contains("DEFAULT_OSS_PROVIDER")||!source.Contains("OPENAI_CHATCOMPLETE_SPEC"))throw new InvalidOperationException("当前 Command Code 桌面版模型结构不匹配，原配置未修改");int begin=source.IndexOf(Begin,StringComparison.Ordinal);if(begin>=0){int end=source.IndexOf(End,begin,StringComparison.Ordinal);if(end<0)throw new InvalidOperationException("旧模型补丁不完整，原文件未修改");source=source.Remove(begin,end+End.Length-begin);}var block=new StringBuilder("\n"+Begin+"\nif(typeof MODEL_OPTIONS==='object'){Object.assign(MODEL_OPTIONS,{\n");for(int i=0;i<valid.Length;i++){string id=Core.Text(valid[i],"id");block.Append("MW_PROXY_").Append(i).Append(":{id:").Append(Core.Json.Serialize(Provider+"/"+id)).Append(",label:").Append(Core.Json.Serialize(id)).Append(",name:").Append(Core.Json.Serialize(id)).Append(",vendorLabel:'工作台代理',provider:DEFAULT_OSS_PROVIDER,spec:").Append(Wire(valid[i])=="openai-responses"&&source.Contains("OPENAI_RESPONSES_SPEC")?"OPENAI_RESPONSES_SPEC":"OPENAI_CHATCOMPLETE_SPEC").Append(",inputModalities:['text'],contextWindow:32768},\n");}block.Append("});}\n"+End+"\n");writes[mainPath]=source+block;}
Commit(writes);}
private static void Commit(Dictionary<string,string> writes){var before=new Dictionary<string,string>();foreach(var entry in writes){before[entry.Key]=File.Exists(entry.Key)?File.ReadAllText(entry.Key,Encoding.UTF8):null;if(before[entry.Key]!=null){string original=entry.Key+".workspace-original.encrypted";if(!File.Exists(original))Core.AtomicWrite(original,Core.Encrypt(before[entry.Key]));Core.AtomicWrite(entry.Key+".workspace-latest.encrypted",Core.Encrypt(before[entry.Key]));}}try{foreach(var entry in writes)Core.AtomicWrite(entry.Key,entry.Value);}catch{foreach(var entry in before){if(entry.Value==null){if(File.Exists(entry.Key))File.Delete(entry.Key);}else Core.AtomicWrite(entry.Key,entry.Value);}throw new InvalidOperationException("客户端配置未完成，已恢复原文件");}}
}
}
